PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS companies (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, salt TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','manager','technician')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, email TEXT, phone TEXT, address TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_customers_company ON customers(company_id,created_at);
CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), customer_id TEXT REFERENCES customers(id), title TEXT NOT NULL, detail TEXT, priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low','Normal','High','Critical')), status TEXT NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','In progress','Resolved','Closed')), assignee TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_tickets_company ON tickets(company_id,created_at);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), customer_id TEXT REFERENCES customers(id), title TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('IT Support','Security','LTE / Internet','Hardware','Cabling','Other')), status TEXT NOT NULL DEFAULT 'Scheduled' CHECK(status IN ('Scheduled','In progress','Awaiting parts','Completed','Cancelled')), technician TEXT, scheduled_date TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_jobs_company ON jobs(company_id,created_at);
CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), customer_id TEXT REFERENCES customers(id), category TEXT NOT NULL CHECK(category IN ('security','hardware','lte','cabling')), title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Active', amount_cents INTEGER NOT NULL DEFAULT 0, details_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_services_company ON services(company_id,category,created_at);
